window.AUTH=window.AUTH||{};window.AUTH["96-643"]={"d":"96-643","id":"1997/96-643","n":"Steel Company v. Citizens for Better Environment","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting respondent","date":"","url":"https://www.justice.gov/osg/media/215521/dl?inline","side":"res","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/steel-company-aka-chicago-steel-and-pickling-company-petitioner-v-citizens-better","n":90}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep523/usrep523083/usrep523083.pdf","tr":false,"items":[{"t":"case","label":"Akins v. Federal Election Common","cite":"101 F.3d 731","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/101/731/","by":{"0":"25"}},{"t":"case","label":"Albermarle Paper Co. v. Moody","cite":"422 U.S. 405","y":1975,"id":"1974/74-389","sc":1,"op":2,"sum":"Stating that \"the indirectness of the injury... may make it substantially more difficult to meet the minimum requirement of Art. III,\" and holding that the injury at issue was too indirect to be redressable.","sumSrc":"opinion","by":{"0":"27"}},{"t":"case","label":"Alyeska Pipeline Serv. Co. v. Wilderness Society","cite":"421 U.S. 240","y":1975,"id":"1974/73-1977","sc":1,"op":2,"sum":"Under the \"American Rule\" that attorneys' fees are not ordinarily recoverable by the prevailing litigant in federal litigation in the absence of statutory authorization, respondents, which had instituted litigation to prevent issuance of Government permits required for construction of the trans-Alaska oil pipeline, cannot recover attorneys' fees from petitioner based on the \"private attorney general\" approach …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Ardestani v. Immigration & Naturalization Serv.","cite":"502 U.S. 129","y":1991,"id":"1991/90-1141","sc":1,"sum":"Administrative deportation proceedings are not adversary adjudications \"under section 554\" and thus do not fall within the category of proceedings for which the EAJA has waived sovereign immunity and authorized the award of attorney's fees and costs.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9"}},{"t":"case","label":"Arizonans for Official English v. Arizona","cite":"117 S. Ct. 1055","y":1997,"id":"1996/95-974","sc":1,"op":1,"sum":"Announced by Justice Ruth Bader Ginsburg, the Court held that the dispute was moot due to the previous resignation of Yniguez. The Court did not rule on the constitutionality of the article.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Atlantic States Legal Found., Inc. v. Buffalo Enve- lope Co.","cite":"823 F. Supp. 1065","y":1993,"court":"W.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./823/1065/","by":{"0":"23"}},{"t":"case","label":"Atlantic States Legal Found., Inc. v. United Musical Instruments U.S.A., Inc.","cite":"61 F.3d 473","y":1995,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/61/473/","op":2,"by":{"0":"5, 23"}},{"t":"case","label":"Atlantic States Legal Found., Inc. v. Whiting Roll- Up Door Mfg. Corp.","cite":"772 F. Supp. 745","y":1991,"court":"W.D. N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./772/745/","op":1,"by":{"0":"23"}},{"t":"case","label":"Bennett v. Spear","cite":"117 S. Ct. 1154","y":1997,"id":"1996/95-813","sc":1,"op":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Chesapeake Bay Found. v. Gwaltney of Smithfield, Ltd.","cite":"911 F. Supp. 1542","y":1985,"court":"E.D. Va.","url":"https://www.courtlistener.com/c/F.%20Supp./911/1542/","by":{"0":"18-19"}},{"t":"case","label":"City of Chicago v. Environmental Defense Fund","cite":"511 U.S. 328","y":1994,"id":"1993/92-1639","sc":1,"op":2,"sum":"Section 3001(i) does not exempt the MWC ash generated by petitioners' facility from Subtitle C regulation as hazardoug waste. Although a pre-§ 3001(i) EPA regulation provided a \"waste stream\" exemption covering household waste from generation through treatment to final disposal of residues, petitioners' facility would not have come within that exemption because it burned something in addition to household waste; the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"City of Mesquite v. Aladdin's Castle, Inc.","cite":"455 U.S. 283","y":1982,"id":"1981/80-1577","sc":1,"sum":"Section 6 of appellant Texas city's licensing ordinance governing coin-operated amusement establishments directs the Chief of Police to consider whether a license applicant has any \"connections with criminal elements.\" After receiving recommendations from the Chief of Police, the Chief Building Inspector, and the City Planner, the City Manager decides whether to grant a license. If he denies the license, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Delaware Valley Toxics Coalition v. Kurz-Hastings, Inc.","cite":"813 F. Supp. 1132","y":1993,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./813/1132/","op":1,"by":{"0":"23"}},{"t":"case","label":"Don't Waste Arizona, Inc. v. McLane Foods, Inc.","cite":"950 F. Supp. 972","y":1996,"court":"D. Ariz.","url":"https://www.courtlistener.com/c/F.%20Supp./950/972/","op":1,"by":{"0":"23"}},{"t":"case","label":"Flast v. Cohen","cite":"392 U.S. 83","y":1968,"id":"1967/416","sc":1,"op":1,"sum":"The Court held that Flast had met both parts of the test.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Foster v. Neilson","cite":"27 U.S. 253","y":1829,"id":"scdb/1829-029","sc":1,"op":4,"sum":"By the treaty of St Ildefonso, made bn the 1st of October 1800, Spain ceded Louisiana to Prance; and' France,'by the treaty of. Paris, signed the 80th of April 1803, ceded it to the United States. Under this treaty the United States claimed the country between the Iberville and the.Perdido. Spain contended that her cession to France-comprehended only that territory which at the.time of the cession was denominated …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Friends of the Earth v. Carey","cite":"535 F.2d 165","y":1976,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/535/165/","by":{"0":"23"}},{"t":"case","label":"Gwaltney of Smithfield, Ltd. v. Chesapeake Bay Found., Inc.","cite":"484 U.S. 49","y":1987,"id":"1987/86-473","sc":1,"op":8,"sum":"Section 505(a) of the Clean Water Act authorizes private citizens to commence a civil action for injunctive relief and/or the imposition of civil penalties in federal district court against any person \"alleged to be in violation\" of the conditions of a National Pollutant Discharge Elimination System (NPDES) permit. Between 1981 and 1984, petitioner repeatedly violated the conditions of its NPDES permit by exceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 11, 12, 15, 16, 28"}},{"t":"case","label":"Hall v. Board of Sch. Commrs.","cite":"656 F.2d 999","y":1981,"court":"5th","url":"https://www.courtlistener.com/c/F.2d/656/999/","by":{"0":"28"}},{"t":"case","label":"Hallstrom v. Tillamook County","cite":"493 U.S. 20","y":1989,"id":"1989/88-42","sc":1,"sum":"Where a party suing under RCRA's citizen suit provision fails to meet the notice and 60-day delay requirements of § 6972(b), the action must be dismissed as barred by the terms of the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16, 17"}},{"t":"case","label":"Havens Realty Corp. v. Coleman","cite":"455 U.S. 363","y":1982,"id":"1981/80-988","sc":1,"op":1,"sum":"Section 804 of the Fair Housing Act of 1968 (Act) makes unlawful various forms of discriminatory housing practices. Section 812(a) authorizes civil actions to enforce §804 and requires that suit be brought within 180 days after the alleged occurrence of a discriminatory practice. A class action for declaratory, injunctive, and monetary relief was brought in Federal District Court against petitioners-Havens Realty …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Hercules, Inc. v. Student Public Interest Research Group of New Jersey, Inc.","cite":"29 E.R.C. 1417","y":1989,"court":"D. N.J.","url":"https://www.courtlistener.com/c/E.R.C./29/1417/","by":{"0":"18"}},{"t":"case","label":"Idaho Sporting Congress v. Computrol, Inc.","cite":"952 F. Supp. 690","y":1996,"court":"D. Id.","url":"https://www.courtlistener.com/c/F.%20Supp./952/690/","by":{"0":"23"}},{"t":"case","label":"Jager v. Douglas County Sch Dist.","cite":"862 F.2d 824","y":1989,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/862/824/","by":{"0":"28"}},{"t":"case","label":"Johnson v. Burkem","cite":"930 F.2d 1202","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/930/1202/","by":{"0":"30"}},{"t":"case","label":"Lewis v. Continental Bank Corp.","cite":"494 U.S. 472","y":1990,"id":"1989/87-1955","sc":1,"op":1,"sum":"Before 1987, the Bank Holding Company Act of 1956 (BHCA) allowed States to prohibit an out-of-state bank holding company from owning an in-state \"bank,\" which was defined to include an institution that both accepted demand deposits and engaged in the commercial lending business. In 1981, appellee, an Illinois bank holding company, applied to Florida to establish and operate an \"industrial savings bank\" (ISB) in that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29"}},{"t":"case","label":"Linda R.S. v. Richard D.","cite":"410 U.S. 614","y":1973,"id":"1972/71-6078","sc":1,"op":4,"sum":"Stating that \"[t]he party who invokes [judicial] power must be able to show ...that he has sustained or is immediately in danger of sustaining some direct injury\" (emphasis in original) (internal quotation marks omitted); injury indirect because it turned on the action of the father, a party not before the Court.","sumSrc":"opinion","by":{"0":"24"}},{"t":"case","label":"Lujan v. Defenders of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"op":11,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"0":"24, 27"}},{"t":"case","label":"Metropolitan Stevedore Co. v. Rambo","cite":"115 S. Ct. 2144","y":1955,"url":"https://www.courtlistener.com/c/S.%20Ct./115/2144/","sc":1,"by":{"0":"10"}},{"t":"case","label":"Mollan v. Torrance","cite":"22 U.S. 537","y":1824,"id":"scdb/1824-022","sc":1,"op":2,"sum":"Stating that \"the indirectness of the injury... may make it substantially more difficult to meet the minimum requirement of Art. III,\" and holding that the injury at issue was too indirect to be redressable.","sumSrc":"opinion","by":{"0":"30"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S 654","y":1988,"url":"https://www.courtlistener.com/c/U.S/487/654/","by":{"0":"16"}},{"t":"case","label":"Pennsylvania v. Delaware Valley Citizens' Council for Clean Air","cite":"478 U.S. 546","y":1986,"url":"https://supreme.justia.com/cases/federal/us/478/546/","sc":1,"by":{"0":"14"}},{"t":"case","label":"United States v. Oregon State Medical Soc.","cite":"343 U.S. 326","y":1952,"id":"scdb/1951-073","sc":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"United States v. W.T. Grant Co.","cite":"345 U.S. 629","y":1953,"id":"scdb/1952-095","sc":1,"op":2,"sum":"Under § 15 of the Clayton Act, the United States sued in a federal district court to enjoin an individual and six corporations from violating § 8 through the holding by the individual of interlocking directorates in three pairs of competing corporations. Thereafter, the individual resigned his directorship in one out of each pair of corporatiQns and filed affidavits disclaiming any intention of resuming such …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27, 28"}},{"t":"case","label":"United States Dep't of Energy, v. Ohio","cite":"503 U.S. 607","y":1992,"id":"1991/90-1341","sc":1,"sum":"Congress has not waived the National Government's sovereign immunity from liability for civil fines imposed by a State for past violations of the CWA or RCRA.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"Vitek v. Jones","cite":"445 U.S. 480","y":1980,"id":"1979/78-1155","sc":1,"sum":"The judgment is affirmed as modified. Pp. 486-497; 497-500. Affirmed as modified.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Warth v. Selding","cite":"422 U.S. 490","y":1975,"id":"1974/73-2024","sc":1,"op":5,"sum":"Stating that \"the indirectness of the injury... may make it substantially more difficult to meet the minimum requirement of Art. III,\" and holding that the injury at issue was too indirect to be redressable.","sumSrc":"opinion","by":{"0":"24"}},{"t":"case","label":"Williams v. Leybold Technologies, Inc.","cite":"784 F. Supp. 765","y":1992,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./784/765/","by":{"0":"23"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["criminal-jury-venue","Criminal Jury and Venue Clause"],["treason","Treason Clause"],["treason-punishment","Punishment of Treason Clause"]],"by":{"0":"8, 23, 24, 27"}},{"t":"usc","label":"42 U.S.C. § 7601","url":"https://www.law.cornell.edu/uscode/text/42/7601","by":{"0":"19"}},{"t":"usc","label":"42 U.S.C. § 7604","url":"https://www.law.cornell.edu/uscode/text/42/7604","subs":["(1)","(b)"],"by":{"0":"19, 19"}},{"t":"usc","label":"33 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/33/1251","by":{"0":"6"}},{"t":"usc","label":"33 U.S.C. § 1365","url":"https://www.law.cornell.edu/uscode/text/33/1365","subs":["(a)","(b)","(b)(1)(A)(ii)","(b)(1)(B)","(c)(1)","(g)"],"stext":{"head":"§1365. Citizen suits","paras":[[0,"(a) Authorization; jurisdiction"],[0,"Except as provided in subsection (b) of this section and section 1319(g)(6) of this title, any citizen may commence a civil action on his own behalf—"],[1,"(1) against any person (including (i) the United States, and (ii) any other governmental instrumentality or agency to the extent permitted by the eleventh amendment to the Constitution) who is alleged to be in violation of (A) an effluent standard or limitation under this chapter or (B) an order issued by the Administrator or a State with respect to such a standard or limitation, or"],[1,"(2) against the Administrator where there is alleged a failure of the Administrator to perform any act or duty under this chapter which is not discretionary with the Administrator."],[0,"The district courts shall have jurisdiction, without regard to the amount in controversy or the citizenship of the parties, to enforce such an effluent standard or limitation, or such an order, or to order the Administrator to perform such act or duty, as the case may be, and to apply any appropriate civil penalties under section 1319(d) of this title."],[0,"(b) Notice"],[0,"No action may be commenced—"],[1,"(1) under subsection (a)(1) of this section—"],[2,"(A) prior to sixty days after the plaintiff has given notice of the alleged violation (i) to the Administrator, (ii) to the State in which the alleged violation occurs, and (iii) to any alleged violator of the standard, limitation, or order, or"],[2,"(B) if the Administrator or State has commenced and is diligently prosecuting a civil or criminal action in a court of the United States, or a State to require compliance with the standard, limitation, or order, but in any such action in a court of the United States any citizen may intervene as a matter of right."],[1,"(2) under subsection (a)(2) of this section prior to sixty days after the plaintiff has given notice of such action to the Administrator,"],[0,"except that such action may be brought immediately after such notification in the case of an action under this section respecting a violation of sections 1316 and 1317(a) of this title. Notice under this subsection shall be given in such manner as the Administrator shall prescribe by regulation."],[0,"(c) Venue; intervention by Administrator; United States interests protected"],[0,"(1) Any action respecting a violation by a discharge source of an effluent standard or limitation or an order respecting such standard or limitation may be brought under this section only in the judicial district in which such source is located."],[0,"(2) In such action under this section, the Administrator, if not a party, may intervene as a matter of right."],[0,"(3) Protection of interests of united states.—Whenever any action is brought under this section in a court of the United States, the plaintiff shall serve a copy of the complaint on the Attorney General and the Administrator. No consent judgment shall be entered in an action in which the United States is not a party prior to 45 days following the receipt of a copy of the proposed consent judgment by the Attorney General and the Administrator."],[0,"(d) Litigation costs"],[0,"The court, in issuing any final order in any action brought pursuant to this section, may award costs of litigation (including reasonable attorney and expert witness fees) to any prevailing or substantially prevailing party, whenever the court determines such award is appropriate. The court may, if a temporary restraining order or preliminary injunction is sought, require the filing of a bond or equivalent security in accordance with the Federal Rules of Civil Procedure."],[0,"(e) Statutory or common law rights not restricted"],[0,"Nothing in this section shall restrict any right which any person (or class of persons) may have under any statute or common law to seek enforcement of any effluent standard or limitation or to seek any other relief (including relief against the Administrator or a State agency)."],[0,"(f) Effluent standard or limitation"],[0,"For purposes of this section, the term \"effluent standard or limitation under this chapter\" means (1) effective July 1, 1973, an unlawful act under subsection (a) of section 1311 of this title; (2) an effluent limitation or other limitation under section 1311 or 1312 of this title; (3) standard of performance under section 1316 of this title; (4) prohibition, effluent standard or pretreatment standards under section 1317 of this title; (5) a standard of performance or requirement under section 1322(p) of this title; (6) a certification under section 1341 of this title; (7) a permit or condition of a permit issued under section 1342 of this title that is in effect under this chapter (including a requirement applicable by reason of section 1323 of this title); or (8) a regulation under section 1345(d) of this title."],[0,"(g) \"Citizen\" defined"],[0,"For the purposes of this section the term \"citizen\" means a person or persons having an interest which is or may be adversely affected."],[0,"(h) Civil action by State Governors"],[0,"A Governor of a State may commence a civil action under subsection (a), without regard to the limitations of subsection (b) of this section, against the Administrator where there is alleged a failure of the Administrator to enforce an effluent standard or limitation under this chapter the violation of which is occurring in another State and is causing an adverse effect on the public health or welfare in his State, or is causing a violation of any water quality requirement in his State."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/1365?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1365. Citizen suits","tname":"Navigation and Navigable Waters","by":{"0":"12, 15, 15, 15, 15, 13"}},{"t":"usc","label":"42 U.S.C. § 9601","url":"https://www.law.cornell.edu/uscode/text/42/9601","by":{"0":"13"}},{"t":"usc","label":"42 U.S.C. § 9659","url":"https://www.law.cornell.edu/uscode/text/42/9659","subs":["(a)(1)"],"by":{"0":"13"}},{"t":"usc","label":"42 U.S.C. § 11001","url":"https://www.law.cornell.edu/uscode/text/42/11001","stext":{"head":"§11001. Establishment of State commissions, planning districts, and local committees","paras":[[0,"(a) Establishment of State emergency response commissions"],[0,"Not later than six months after October 17, 1986, the Governor of each State shall appoint a State emergency response commission. The Governor may designate as the State emergency response commission one or more existing emergency response organizations that are State-sponsored or appointed. The Governor shall, to the extent practicable, appoint persons to the State emergency response commission who have technical expertise in the emergency response field. The State emergency response commission shall appoint local emergency planning committees under subsection (c) and shall supervise and coordinate the activities of such committees. The State emergency response commission shall establish procedures for receiving and processing requests from the public for information under section 11044 of this title, including tier II information under section 11022 of this title. Such procedures shall include the designation of an official to serve as coordinator for information. If the Governor of any State does not designate a State emergency response commission within such period, the Governor shall operate as the State emergency response commission until the Governor makes such designation."],[0,"(b) Establishment of emergency planning districts"],[0,"Not later than nine months after October 17, 1986, the State emergency response commission shall designate emergency planning districts in order to facilitate preparation and implementation of emergency plans. Where appropriate, the State emergency response commission may designate existing political subdivisions or multijurisdictional planning organizations as such districts. In emergency planning areas that involve more than one State, the State emergency response commissions of all potentially affected States may designate emergency planning districts and local emergency planning committees by agreement. In making such designation, the State emergency response commission shall indicate which facilities subject to the requirements of this subchapter are within such emergency planning district."],[0,"(c) Establishment of local emergency planning committees"],[0,"Not later than 30 days after designation of emergency planning districts or 10 months after October 17, 1986, whichever is earlier, the State emergency response commission shall appoint members of a local emergency planning committee for each emergency planning district. Each committee shall include, at a minimum, representatives from each of the following groups or organizations: elected State and local officials; law enforcement, civil defense, firefighting, first aid, health, local environmental, hospital, and transportation personnel; broadcast and print media; community groups; and owners and operators of facilities subject to the requirements of this subchapter. Such committee shall appoint a chairperson and shall establish rules by which the committee shall function. Such rules shall include provisions for public notification of committee activities, public meetings to discuss the emergency plan, public comments, response to such comments by the committee, and distribution of the emergency plan. The local emergency planning committee shall establish procedures for receiving and processing requests from the public for information under section 11044 of this title, including tier II information under section 11022 of this title. Such procedures shall include the designation of an official to serve as coordinator for information."],[0,"(d) Revisions"],[0,"A State emergency response commission may revise its designations and appointments under subsections (b) and (c) as it deems appropriate. Interested persons may petition the State emergency response commission to modify the membership of a local emergency planning committee."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/11001?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§11001. Establishment of State commissions, planning districts, and local committees","tname":"The Public Health and Welfare","by":{"0":"1"}},{"t":"usc","label":"42 U.S.C. § 11002","url":"https://www.law.cornell.edu/uscode/text/42/11002","subs":["(c)"],"by":{"0":"21"}},{"t":"usc","label":"42 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/42/1103","subs":["(d)"],"by":{"0":"21"}},{"t":"usc","label":"42 U.S.C. § 11021","url":"https://www.law.cornell.edu/uscode/text/42/11021","subs":["(c)","(e)(1)"],"by":{"0":"22, 21, 21"}},{"t":"usc","label":"42 U.S.C. § 11022","url":"https://www.law.cornell.edu/uscode/text/42/11022","subs":["(a)","(a)(1)","(d)(1)(B)","(d)(2)","(e)(1)"],"stext":{"head":"§11022. Emergency and hazardous chemical inventory forms","paras":[[0,"(a) Basic requirement"],[0,"(1) The owner or operator of any facility which is required to prepare or have available a material safety data sheet for a hazardous chemical under the Occupational Safety and Health Act of 1970 [29 U.S.C. 651 et seq.] and regulations promulgated under that Act shall prepare and submit an emergency and hazardous chemical inventory form (hereafter in this chapter referred to as an \"inventory form\") to each of the following:"],[1,"(A) The appropriate local emergency planning committee."],[1,"(B) The State emergency response commission."],[1,"(C) The fire department with jurisdiction over the facility."],[0,"(2) The inventory form containing tier I information (as described in subsection (d)(1)) shall be submitted on or before March 1, 1988, and annually thereafter on March 1, and shall contain data with respect to the preceding calendar year. The preceding sentence does not apply if an owner or operator provides, by the same deadline and with respect to the same calendar year, tier II information (as described in subsection (d)(2)) to the recipients described in paragraph (1)."],[0,"(3) An owner or operator may meet the requirements of this section with respect to a hazardous chemical which is a mixture by doing one of the following:"],[1,"(A) Providing information on the inventory form on each element or compound in the mixture which is a hazardous chemical. If more than one mixture has the same element or compound, only one listing on the inventory form for the element or compound at the facility is necessary."],[1,"(B) Providing information on the inventory form on the mixture itself."],[0,"(b) Thresholds"],[0,"The Administrator may establish threshold quantities for hazardous chemicals covered by this section below which no facility shall be subject to the provisions of this section. The threshold quantities may, in the Administrator's discretion, be based on classes of chemicals or categories of facilities."],[0,"(c) Hazardous chemicals covered"],[0,"A hazardous chemical subject to the requirements of this section is any hazardous chemical for which a material safety data sheet or a listing is required under section 11021 of this title."],[0,"(d) Contents of form"],[0,"(1) Tier I information"],[0,"(A) Aggregate information by category"],[2,"An inventory form shall provide the information described in subparagraph (B) in aggregate terms for hazardous chemicals in categories of health and physical hazards as set forth under the Occupational Safety and Health Act of 1970 [29 U.S.C. 651 et seq.] and regulations promulgated under that Act."],[0,"(B) Required information"],[2,"The information referred to in subparagraph (A) is the following:"],[3,"(i) An estimate (in ranges) of the maximum amount of hazardous chemicals in each category present at the facility at any time during the preceding calendar year."],[3,"(ii) An estimate (in ranges) of the average daily amount of hazardous chemicals in each category present at the facility during the preceding calendar year."],[3,"(iii) The general location of hazardous chemicals in each category."],[0,"(C) Modifications"],[2,"For purposes of reporting information under this paragraph, the Administrator may—"],[3,"(i) modify the categories of health and physical hazards as set forth under the Occupational Safety and Health Act of 1970 [29 U.S.C. 651 et seq.] and regulations promulgated under that Act by requiring information to be reported in terms of groups of hazardous chemicals which present similar hazards in an emergency, or"],[3,"(ii) require reporting on individual hazardous chemicals of special concern to emergency response personnel."],[0,"(2) Tier II information"],[1,"An inventory form shall provide the following additional information for each hazardous chemical present at the facility, but only upon request and in accordance with subsection (e):"],[2,"(A) The chemical name or the common name of the chemical as provided on the material safety data sheet."],[2,"(B) An estimate (in ranges) of the maximum amount of the hazardous chemical present at the facility at any time during the preceding calendar year."],[2,"(C) An estimate (in ranges) of the average daily amount of the hazardous chemical present at the facility during the preceding calendar year."],[2,"(D) A brief description of the manner of storage of the hazardous chemical."],[2,"(E) The location at the facility of the hazardous chemical."],[2,"(F) An indication of whether the owner elects to withhold location information of a specific hazardous chemical from disclosure to the public under section 11044 of this title."],[0,"(e) Availability of tier II information"],[0,"(1) Availability to State commissions, local committees, and fire departments"],[1,"Upon request by a State emergency response commission, a local emergency planning committee, or a fire department with jurisdiction over the facility, the owner or operator of a facility shall provide tier II information, as described in subsection (d), to the person making the request. Any such request shall be with respect to a specific facility."],[0,"(2) Availability to other State and local officials"],[1,"A State or local official acting in his or her official capacity may have access to tier II information by submitting a request to the State emergency response commission or the local emergency planning committee. Upon receipt of a request for tier II information, the State commission or local committee shall, pursuant to paragraph (1), request the facility owner or operator for the tier II information and make available such information to the official."],[0,"(3) Availability to public"],[0,"(A) In general"],[2,"Any person may request a State emergency response commission or local emergency planning committee for tier II information relating to the preceding calendar year with respect to a facility. Any such request shall be in writing and shall be with respect to a specific facility."],[0,"(B) Automatic provision of information to public"],[2,"Any tier II information which a State emergency response commission or local emergency planning committee has in its possession shall be made available to a person making a request under this paragraph in accordance with section 11044 of this title. If the State emergency response commission or local emergency planning committee does not have the tier II information in its possession, upon a request for tier II information the State emergency response commission or local emergency planning committee shall, pursuant to paragraph (1), request the facility owner or operator for tier II information with respect to a hazardous chemical which a facility has stored in an amount in excess of 10,000 pounds present at the facility at any time during the preceding calendar year and make such information available in accordance with section 11044 of this title to the person making the request."],[0,"(C) Discretionary provision of information to public"],[2,"In the case of tier II information which is not in the possession of a State emergency response commission or local emergency planning committee and which is with respect to a hazardous chemical which a facility has stored in an amount less than 10,000 pounds present at the facility at any time during the preceding calendar year, a request from a person must include the general need for the information. The State emergency response commission or local emergency planning committee may, pursuant to paragraph (1), request the facility owner or operator for the tier II information on behalf of the person making the request. Upon receipt of any information requested on behalf of such person, the State emergency response commission or local emergency planning committee shall make the information available in accordance with section 11044 of this title to the person."],[0,"(D) Response in 45 days"],[2,"A State emergency response commission or local emergency planning committee shall respond to a request for tier II information under this paragraph no later than 45 days after the date of receipt of the request."],[0,"(4) Availability to community water systems"],[0,"(A) In general"],[2,"An affected community water system may have access to tier II information by submitting a request to the State emergency response commission or the local emergency planning committee. Upon receipt of a request for tier II information, the State commission or local committee shall, pursuant to paragraph (1), request the facility owner or operator for the tier II information and make available such information to the affected community water system."],[0,"(B) Definition"],[2,"In this paragraph, the term \"affected community water system\" means a community water system (as defined in section 300f(15) of this title) that receives supplies of drinking water from a source water area, delineated under section 300j–13 of this title, in which a facility that is required to prepare and submit an inventory form under subsection (a)(1) is located."],[0,"(f) Fire department access"],[0,"Upon request to an owner or operator of a facility which files an inventory form under this section by the fire department with jurisdiction over the facility, the owner or operator of the facility shall allow the fire department to conduct an on-site inspection of the facility and shall provide to the fire department specific location information on hazardous chemicals at the facility."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/11022?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§11022. Emergency and hazardous chemical inventory forms","tname":"The Public Health and Welfare","by":{"0":"4, 13, 14, 15, 19, 22, 25, 2, 4, 7, 9, 10, 15, 13, 13, 14, 21"}},{"t":"usc","label":"42 U.S.C. § 11023","url":"https://www.law.cornell.edu/uscode/text/42/11023","subs":["(a)","(g)(l)(C)","(g)(2)","(h)","(j)"],"by":{"0":"4, 13, 14, 15, 19, 25, 2,4, 8, 9, 10,15, 21, 13, 14, 2, 3, 14, 22, 3"}},{"t":"usc","label":"42 U.S.C. § 11042","url":"https://www.law.cornell.edu/uscode/text/42/11042","subs":["(b)(1)"],"by":{"0":"21"}},{"t":"usc","label":"42 U.S.C. § 11043","url":"https://www.law.cornell.edu/uscode/text/42/11043","subs":["(b)"],"by":{"0":"14"}},{"t":"usc","label":"42 U.S.C. § 11044","url":"https://www.law.cornell.edu/uscode/text/42/11044","subs":["(a)","(b)"],"by":{"0":"3, 14, 3"}},{"t":"usc","label":"42 U.S.C. § 11045","url":"https://www.law.cornell.edu/uscode/text/42/11045","subs":["(c)"],"stext":{"head":"§11045. Enforcement","paras":[[0,"(a) Civil penalties for emergency planning"],[0,"The Administrator may order a facility owner or operator (except an owner or operator of a facility designated under section 11002(b)(2) of this title) to comply with section 11002(c) of this title and section 11003(d) of this title. The United States district court for the district in which the facility is located shall have jurisdiction to enforce the order, and any person who violates or fails to obey such an order shall be liable to the United States for a civil penalty of not more than $25,000 for each day in which such violation occurs or such failure to comply continues."],[0,"(b) Civil, administrative, and criminal penalties for emergency notification"],[0,"(1) Class I administrative penalty"],[1,"(A) A civil penalty of not more than $25,000 per violation may be assessed by the Administrator in the case of a violation of the requirements of section 11004 of this title."],[1,"(B) No civil penalty may be assessed under this subsection unless the person accused of the violation is given notice and opportunity for a hearing with respect to the violation."],[1,"(C) In determining the amount of any penalty assessed pursuant to this subsection, the Administrator shall take into account the nature, circumstances, extent and gravity of the violation or violations and, with respect to the violator, ability to pay, any prior history of such violations, the degree of culpability, economic benefit or savings (if any) resulting from the violation, and such other matters as justice may require."],[0,"(2) Class II administrative penalty"],[1,"A civil penalty of not more than $25,000 per day for each day during which the violation continues may be assessed by the Administrator in the case of a violation of the requirements of section 11004 of this title. In the case of a second or subsequent violation the amount of such penalty may be not more than $75,000 for each day during which the violation continues. Any civil penalty under this subsection shall be assessed and collected in the same manner, and subject to the same provisions, as in the case of civil penalties assessed and collected under section 2615 of title 15. In any proceeding for the assessment of a civil penalty under this subsection the Administrator may issue subpoenas for the attendance and testimony of witnesses and the production of relevant papers, books, and documents and may promulgate rules for discovery procedures."],[0,"(3) Judicial assessment"],[1,"The Administrator may bring an action in the United States District 1 court for the appropriate district to assess and collect a penalty of not more than $25,000 per day for each day during which the violation continues in the case of a violation of the requirements of section 11004 of this title. In the case of a second or subsequent violation, the amount of such penalty may be not more than $75,000 for each day during which the violation continues."],[0,"(4) Criminal penalties"],[1,"Any person who knowingly and willfully fails to provide notice in accordance with section 11004 of this title shall, upon conviction, be fined not more than $25,000 or imprisoned for not more than two years, or both (or in the case of a second or subsequent conviction, shall be fined not more than $50,000 or imprisoned for not more than five years, or both)."],[0,"(c) Civil and administrative penalties for reporting requirements"],[0,"(1) Any person (other than a governmental entity) who violates any requirement of section 11022 or 11023 of this title shall be liable to the United States for a civil penalty in an amount not to exceed $25,000 for each such violation."],[0,"(2) Any person (other than a governmental entity) who violates any requirement of section 11021 or 11043(b) of this title, and any person who fails to furnish to the Administrator information required under section 11042(a)(2) of this title shall be liable to the United States for a civil penalty in an amount not to exceed $10,000 for each such violation."],[0,"(3) Each day a violation described in paragraph (1) or (2) continues shall, for purposes of this subsection, constitute a separate violation."],[0,"(4) The Administrator may assess any civil penalty for which a person is liable under this subsection by administrative order or may bring an action to assess and collect the penalty in the United States district court for the district in which the person from whom the penalty is sought resides or in which such person's principal place of business is located."],[0,"(d) Civil, administrative, and criminal penalties with respect to trade secrets"],[0,"(1) Civil and administrative penalty for frivolous claims"],[1,"If the Administrator determines—"],[2,"(A)(i) under section 11042(d)(4) of this title that an explanation submitted by a trade secret claimant presents insufficient assertions to support a finding that a specific chemical identity is a trade secret, or (ii) after receiving supplemental supporting detailed information under section 11042(d)(3)(A) of this title, that the specific chemical identity is not a trade secret; and"],[2,"(B) that the trade secret claim is frivolous,"],[1,"the trade secret claimant is liable for a penalty of $25,000 per claim. The Administrator may assess the penalty by administrative order or may bring an action in the appropriate district court of the United States to assess and collect the penalty."],[0,"(2) Criminal penalty for disclosure of trade secret information"],[1,"Any person who knowingly and willfully divulges or discloses any information entitled to protection under section 11042 of this title shall, upon conviction, be subject to a fine of not more than $20,000 or to imprisonment not to exceed one year, or both."],[0,"(e) Special enforcement provisions for section 11043"],[0,"Whenever any facility owner or operator required to provide information under section 11043 of this title to a health professional who has requested such information fails or refuses to provide such information in accordance with such section, such health professional may bring an action in the appropriate United States district court to require such facility owner or operator to provide the information. Such court shall have jurisdiction to issue such orders and take such other action as may be necessary to enforce the requirements of section 11043 of this title."],[0,"(f) Procedures for administrative penalties"],[0,"(1) Any person against whom a civil penalty is assessed under this section may obtain review thereof in the appropriate district court of the United States by filing a notice of appeal in such court within 30 days after the date of such order and by simultaneously sending a copy of such notice by certified mail to the Administrator. The Administrator shall promptly file in such court a certified copy of the record upon which such violation was found or such penalty imposed. If any person fails to pay an assessment of a civil penalty after it has become a final and unappealable order or after the appropriate court has entered final judgment in favor of the United States, the Administrator may request the Attorney General of the United States to institute a civil action in an appropriate district court of the United States to collect the penalty, and such court shall have jurisdiction to hear and decide any such action. In hearing such action, the court shall have authority to review the violation and the assessment of the civil penalty on the record."],[0,"(2) The Administrator may issue subpoenas for the attendance and testimony of witnesses and the production of relevant papers, books, or documents in connection with hearings under this section. In case of contumacy or refusal to obey a subpoena issued pursuant to this paragraph and served upon any person, the district court of the United States for any district in which such person is found, resides, or transacts business, upon application by the United States and after notice to such person, shall have jurisdiction to issue an order requiring such person to appear and give testimony before the administrative law judge or to appear and produce documents before the administrative law judge, or both, and any failure to obey such order of the court may be punished by such court as a contempt thereof."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/11045?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§11045. Enforcement","tname":"The Public Health and Welfare","by":{"0":"18"}},{"t":"usc","label":"42 U.S.C. § 11046","url":"https://www.law.cornell.edu/uscode/text/42/11046","subs":["(a)","(a)(1)","(a)(1)(A)(iii)","(a)(1)(A)(iv)","(a)(2)","(b)(l)","(d)","(d)(1)","(e)","(h)(1)"],"stext":{"head":"§11046. Civil actions","paras":[[0,"(a) Authority to bring civil actions"],[0,"(1) Citizen suits"],[1,"Except as provided in subsection (e), any person may commence a civil action on his own behalf against the following:"],[2,"(A) An owner or operator of a facility for failure to do any of the following:"],[3,"(i) Submit a followup emergency notice under section 11004(c) of this title."],[3,"(ii) Submit a material safety data sheet or a list under section 11021(a) of this title."],[3,"(iii) Complete and submit an inventory form under section 11022(a) of this title containing tier I information as described in section 11022(d)(1) of this title unless such requirement does not apply by reason of the second sentence of section 11022(a)(2) of this title."],[3,"(iv) Complete and submit a toxic chemical release form under section 11023(a) of this title."],[2,"(B) The Administrator for failure to do any of the following:"],[3,"(i) Publish inventory forms under section 11022(g) of this title."],[3,"(ii) Respond to a petition to add or delete a chemical under section 11023(e)(1) of this title within 180 days after receipt of the petition."],[3,"(iii) Publish a toxic chemical release form under 11023(g) 1 of this title."],[3,"(iv) Establish a computer database in accordance with section 11023(j) of this title."],[3,"(v) Promulgate trade secret regulations under section 11042(c) of this title."],[3,"(vi) Render a decision in response to a petition under section 11042(d) of this title within 9 months after receipt of the petition."],[2,"(C) The Administrator, a State Governor, or a State emergency response commission, for failure to provide a mechanism for public availability of information in accordance with section 11044(a) of this title."],[2,"(D) A State Governor or a State emergency response commission for failure to respond to a request for tier II information under section 11022(e)(3) of this title within 120 days after the date of receipt of the request."],[0,"(2) State or local suits"],[1,"(A) Any State or local government may commence a civil action against an owner or operator of a facility for failure to do any of the following:"],[2,"(i) Provide notification to the emergency response commission in the State under section 11002(c) of this title."],[2,"(ii) Submit a material safety data sheet or a list under section 11021(a) of this title."],[2,"(iii) Make available information requested under section 11021(c) of this title."],[2,"(iv) Complete and submit an inventory form under section 11022(a) of this title containing tier I information unless such requirement does not apply by reason of the second sentence of section 11022(a)(2) of this title."],[1,"(B) Any State emergency response commission or local emergency planning committee may commence a civil action against an owner or operator of a facility for failure to provide information under section 11003(d) of this title or for failure to submit tier II information under section 11022(e)(1) of this title."],[1,"(C) Any State may commence a civil action against the Administrator for failure to provide information to the State under section 11042(g) of this title."],[0,"(b) Venue"],[0,"(1) Any action under subsection (a) against an owner or operator of a facility shall be brought in the district court for the district in which the alleged violation occurred."],[0,"(2) Any action under subsection (a) against the Administrator may be brought in the United States District Court for the District of Columbia."],[0,"(c) Relief"],[0,"The district court shall have jurisdiction in actions brought under subsection (a) against an owner or operator of a facility to enforce the requirement concerned and to impose any civil penalty provided for violation of that requirement. The district court shall have jurisdiction in actions brought under subsection (a) against the Administrator to order the Administrator to perform the act or duty concerned."],[0,"(d) Notice"],[0,"(1) No action may be commenced under subsection (a)(1)(A) prior to 60 days after the plaintiff has given notice of the alleged violation to the Administrator, the State in which the alleged violation occurs, and the alleged violator. Notice under this paragraph shall be given in such manner as the Administrator shall prescribe by regulation."],[0,"(2) No action may be commenced under subsection (a)(1)(B) or (a)(1)(C) prior to 60 days after the date on which the plaintiff gives notice to the Administrator, State Governor, or State emergency response commission (as the case may be) that the plaintiff will commence the action. Notice under this paragraph shall be given in such manner as the Administrator shall prescribe by regulation."],[0,"(e) Limitation"],[0,"No action may be commenced under subsection (a) against an owner or operator of a facility if the Administrator has commenced and is diligently pursuing an administrative order or civil action to enforce the requirement concerned or to impose a civil penalty under this Act with respect to the violation of the requirement."],[0,"(f) Costs"],[0,"The court, in issuing any final order in any action brought pursuant to this section, may award costs of litigation (including reasonable attorney and expert witness fees) to the prevailing or the substantially prevailing party whenever the court determines such an award is appropriate. The court may, if a temporary restraining order or preliminary injunction is sought, require the filing of a bond or equivalent security in accordance with the Federal Rules of Civil Procedure."],[0,"(g) Other rights"],[0,"Nothing in this section shall restrict or expand any right which any person (or class of persons) may have under any Federal or State statute or common law to seek enforcement of any requirement or to seek any other relief (including relief against the Administrator or a State agency)."],[0,"(h) Intervention"],[0,"(1) By the United States"],[1,"In any action under this section the United States or the State, or both, if not a party, may intervene as a matter of right."],[0,"(2) By persons"],[1,"In any action under this section, any person may intervene as a matter of right when such person has a direct interest which is or may be adversely affected by the action and the disposition of the action may, as a practical matter, impair or impede the person's ability to protect that interest unless the Administrator or the State shows that the person's interest is adequately represented by existing parties in the action."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/11046?type=usc&year=mostrecent&link-type=html"},"op":13,"head":"§11046. Civil actions","tname":"The Public Health and Welfare","by":{"0":"7, 13, 4, 7, 10, 3, 4, 7, 9, 3, 3, 3, 6, 8, 10, 15, 17, 4, 8, 11, 15, 17, 15, 17, 18"}},{"t":"usc","label":"42 U.S.C. § 11049","url":"https://www.law.cornell.edu/uscode/text/42/11049","subs":["(7)"],"by":{"0":"16"}},{"t":"law","label":"Pub. L. No. 99-499","url":"https://www.govinfo.gov/link/statute/100/1613","by":{"0":"13"}},{"t":"usc","label":"18 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/18/1001","by":{"0":"20"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(b)(6)"],"by":{"0":"5"}},{"t":"reg","label":"President William J. Clinton, Memorandum for the Administrator of the Environmental Protection Agency and the Heads of Executive Departments, 60 Fed. Reg. 41,791","url":"https://www.govinfo.gov/link/fr/60/41791","by":{"0":"3"}}]};